'use strict';
// Validate a native Go cover profile against a complete Go source inventory.
//
// What is measured (Go's profile cannot yield anything finer):
//   lines    = statements: the sum of each block's statement count; a statement is covered
//              when its block was entered in any aggregated run.
//   branches = basic blocks: every profile block is one required entry; an `if` body, `case`
//              clause, loop body or function entry is a block. Implicit false/no-match exits and
//              short-circuit operands are NOT separate outcomes because Go does not record them.
const fs = require('node:fs');
const path = require('node:path');
const {fail, realPath, isInside, emptyCounts} = require('./coverage-util.cjs');

const EXCLUDED_DIRECTORIES = new Set(['vendor', 'testdata', 'node_modules']);
const ROW = /^(.+):([1-9][0-9]*)\.([1-9][0-9]*),([1-9][0-9]*)\.([1-9][0-9]*) ([0-9]+) ([0-9]+)$/;
const LINE_BREAKS = /\r\n|\n|\r/;

const excludedDirectory = name => name.startsWith('.') || name.startsWith('_') || EXCLUDED_DIRECTORIES.has(name);

// Remove comments, strings and runes so keyword scans see only code.
function lexGo(text, file) {
  let code = '';
  for (let index = 0; index < text.length;) {
    const char = text[index];
    if (text.startsWith('//', index)) {
      const end = text.indexOf('\n', index);
      index = end < 0 ? text.length : end;
    } else if (text.startsWith('/*', index)) {
      const end = text.indexOf('*/', index + 2);
      if (end < 0) fail(`Invalid Go application source: ${file}`);
      index = end + 2;
    } else if (char === '`') {
      const end = text.indexOf('`', index + 1);
      if (end < 0) fail(`Invalid Go application source: ${file}`);
      index = end + 1;
    } else if (char === '"' || char === "'") {
      let end = index + 1;
      while (end < text.length && text[end] !== char && text[end] !== '\n') end += text[end] === '\\' ? 2 : 1;
      if (text[end] !== char) fail(`Invalid Go application source: ${file}`);
      index = end + 1;
    } else {
      code += char;
      index++;
    }
  }
  return code;
}

// The module path and root directory of the nearest enclosing go.mod.
function moduleOf(root) {
  let directory = root;
  for (;;) {
    const candidate = path.join(directory, 'go.mod');
    if (fs.existsSync(candidate)) {
      const match = /^module\s+("?)([^\s"]+)\1\s*(?:\/\/.*)?$/m.exec(fs.readFileSync(candidate, 'utf8'));
      if (!match) fail('go.mod has no module path');
      return {modulePath: match[2], moduleRoot: directory};
    }
    const parent = path.dirname(directory);
    if (parent === directory) fail('No go.mod found for the Go source directory');
    directory = parent;
  }
}

function inventory(root, cwd) {
  const sources = new Map();
  const walk = directory => {
    for (const entry of fs.readdirSync(directory, {withFileTypes: true})) {
      const file = path.join(directory, entry.name);
      if (entry.isSymbolicLink()) {
        if (entry.name.endsWith('.go') || fs.statSync(file, {throwIfNoEntry: false})?.isDirectory()) fail(`Symbolic Go application source: ${file}`);
      } else if (entry.isDirectory()) {
        if (!excludedDirectory(entry.name) && !fs.existsSync(path.join(file, 'go.mod'))) walk(file);
      } else if (entry.name.endsWith('.go') && !entry.name.endsWith('_test.go')) {
        let text;
        try {text = new TextDecoder('utf-8', {fatal: true}).decode(fs.readFileSync(file));}
        catch {fail(`Invalid Go application source: ${file}`);}
        const code = lexGo(text, file);
        const lines = text.split(LINE_BREAKS);
        if (lines[lines.length - 1] === '') lines.pop();
        sources.set(realPath(file, cwd), {limit: lines.length, mustAppear: /\bfunc\b/.test(code)});
      }
    }
  };
  walk(root);
  if (!sources.size) fail('No application Go sources found');
  return sources;
}

const integer = value => {
  const number = Number(value);
  return Number.isSafeInteger(number) ? number : fail('Go cover profile numbers must be safe integers');
};

// Parse rows into per-file block maps, merging repeated rows as the union of runs.
function blocks(text, modulePath, moduleRoot, root, sources, cwd) {
  const rows = text.split(LINE_BREAKS);
  if (rows[rows.length - 1] === '') rows.pop();
  if (!/^mode: (?:set|count|atomic)$/.test(rows[0] ?? '')) fail('Expected a native Go cover profile with a set, count or atomic mode line');
  const files = new Map();
  for (const row of rows.slice(1)) {
    const match = ROW.exec(row);
    if (!match) fail('Malformed Go cover profile row');
    const [, name, startLine, startColumn, endLine, endColumn, statements, count] = match;
    const block = {start: [integer(startLine), integer(startColumn)], end: [integer(endLine), integer(endColumn)],
      statements: integer(statements), hit: integer(count) > 0};
    if (block.start[0] > block.end[0] || (block.start[0] === block.end[0] && block.start[1] > block.end[1])) fail('Go cover block ends before it starts');
    if (!name.startsWith(modulePath + '/')) continue;
    const file = realPath(path.join(moduleRoot, name.slice(modulePath.length + 1)), cwd);
    if (!isInside(file, root)) continue;
    const source = sources.get(file);
    if (!source) fail(`Unexpected Go application coverage: ${name}`);
    if (block.end[0] > source.limit) fail(`Go cover block lies beyond the source file: ${name}`);
    const key = [...block.start, ...block.end].join(',');
    const known = files.get(file) ?? files.set(file, new Map()).get(file);
    const previous = known.get(key);
    if (previous && previous.statements !== block.statements) fail(`Conflicting Go cover rows for one block: ${name}`);
    known.set(key, previous ? {...previous, hit: previous.hit || block.hit} : block);
  }
  return files;
}

function counters(text, sourceDirectory, cwd, detail) {
  if (typeof text !== 'string') fail('Expected a Go cover profile as text');
  const root = realPath(sourceDirectory, cwd);
  const {modulePath, moduleRoot} = moduleOf(root);
  const sources = inventory(root, cwd);
  const files = blocks(text, modulePath, moduleRoot, root, sources, cwd);
  const counts = emptyCounts();
  for (const [file, known] of files) {
    const ordered = [...known.values()].sort((a, b) => a.start[0] - b.start[0] || a.start[1] - b.start[1]);
    const lineMap = new Map();
    const branchItems = [];
    ordered.forEach((block, index) => {
      const before = ordered[index - 1];
      if (before && (before.end[0] > block.start[0] || (before.end[0] === block.start[0] && before.end[1] > block.start[1]))) {
        fail(`Overlapping Go cover blocks; the profile does not match the source: ${file}`);
      }
      counts.lines[0] += block.statements;
      if (block.hit) counts.lines[1] += block.statements;
      counts.branches[0]++;
      if (block.hit) counts.branches[1]++;
      if (detail) {
        // A block is the finest unit Go records: every line it spans is covered only if the block ran.
        for (let line = block.start[0]; line <= block.end[0]; line++) lineMap.set(line, (lineMap.get(line) ?? true) && block.hit);
        branchItems.push({from: block.start[0], to: block.end[0], covered: block.hit});
      }
    });
    if (detail) detail.set(file, {lines: lineMap, branches: branchItems});
  }
  const missing = [...sources].filter(([file, source]) => !files.has(file) && source.mustAppear).map(([file]) => file);
  if (missing.length) {
    fail('Go application sources missing from the profile (unloaded package, build constraint or GOOS/GOARCH suffix; use -coverpkg=./...): ' + missing.sort().join(', '));
  }
  return counts;
}

module.exports = {counters, inventory, moduleOf};

'use strict';
// Validate a native Go outcome report written by tools/goinstr against a complete Go source inventory.
//
// The report is measured, never inferred: tools/goinstr rewrites each application source so every executed
// statement and every taken outcome of a decision is written when it is taken. What is counted:
//   lines    = distinct source lines that start a statement; a line is covered only when every statement
//              starting on it executed.
//   branches = outcomes: if true/false (including the implicit false), each && / || operand true/false, loop
//              condition true/false, loop zero-entry, range enter, every switch/type-switch/select clause, the
//              switch no-match, and a switch default. See docs/go-instrumenter.md.
// Every inventoried application file must be reported and bound to its current bytes; a file excluded from every
// declared build, a stale or unknown file and any malformed field is an explicit error.
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const {fail, isObject, realPath, isInside, emptyCounts} = require('./coverage-util.cjs');
const {inventory, moduleOf} = require('./coverage-go.cjs');

const MAX_BUILDS = 16;
const word = /^[a-z0-9_]{1,40}$/;

const keysAre = (value, required, optional = []) => isObject(value) && required.every(key => Object.hasOwn(value, key)) &&
  Object.keys(value).every(key => required.includes(key) || optional.includes(key));
const count = value => Number.isSafeInteger(value) && value >= 0 ? value : fail('Go outcome counts must be nonnegative safe integers');
const text = value => typeof value === 'string' && value.length > 0 && value.length < 300 ? value : fail('Go outcome fields must be nonempty strings');

function build(value) {
  if (!keysAre(value, ['goos', 'goarch', 'tags']) || !word.test(value.goos) || !word.test(value.goarch) || !Array.isArray(value.tags) ||
      value.tags.some(tag => typeof tag !== 'string' || !/^[A-Za-z0-9_.]{1,40}$/.test(tag))) {
    fail('Each Go outcome build requires goos, goarch and tags');
  }
}

function header(report, modulePath) {
  if (!keysAre(report, ['schema', 'version', 'go_version', 'module', 'builds', 'files'])) fail('Malformed Go outcome report');
  if (report.schema !== 'clouseau-go-outcomes' || report.version !== 1) fail('Unsupported Go outcome report schema or version');
  if (typeof report.go_version !== 'string' || !/^go1\.[0-9]+(?:\.[0-9]+)?(?:rc[0-9]+)?$/.test(report.go_version)) fail('Go outcome report has no Go version');
  if (report.module !== modulePath) fail('The Go outcome report belongs to another module');
  if (!Array.isArray(report.builds) || !report.builds.length || report.builds.length > MAX_BUILDS) fail('A Go outcome report requires one to 16 declared builds');
  report.builds.forEach(build);
  if (!Array.isArray(report.files)) fail('Malformed Go outcome report');
}

function sourceOf(entry, moduleRoot, root, sources, seen, cwd) {
  if (!keysAre(entry, ['path', 'sha256', 'lines', 'status', 'statements', 'outcomes'], ['reason'])) fail('Malformed Go outcome file entry');
  const relative = text(entry.path);
  if (relative.startsWith('/') || relative.includes('\\') || relative.split('/').some(part => !part || part === '.' || part === '..')) {
    fail(`Unsafe Go outcome path: ${relative}`);
  }
  const file = realPath(path.join(moduleRoot, relative), cwd);
  if (!isInside(file, root)) fail(`Go outcome path escapes the source directory: ${relative}`);
  const source = sources.get(file);
  if (!source) fail(`Unexpected Go application outcomes: ${relative}`);
  if (seen.has(file)) fail(`Duplicate Go outcome entry: ${relative}`);
  seen.add(file);
  return {file, source, relative};
}

function bind(entry, file, source, relative) {
  if (entry.sha256 !== crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex') || entry.lines !== source.limit) {
    fail(`Go outcome report is stale or from another source: ${relative}`);
  }
}

const lineOf = (value, limit) => {
  const line = count(value);
  return line >= 1 && line <= limit ? line : fail('A Go outcome lies beyond the source file');
};

function measure(entry, limit, counts) {
  if (!Array.isArray(entry.statements) || !Array.isArray(entry.outcomes)) fail('Malformed Go outcome file entry');
  const lines = new Map();
  for (const statement of entry.statements) {
    if (!keysAre(statement, ['line', 'hits'])) fail('Malformed Go statement entry');
    const line = lineOf(statement.line, limit);
    const ran = count(statement.hits) > 0;
    lines.set(line, (lines.get(line) ?? true) && ran);
  }
  const keys = new Set();
  const branches = [];
  for (const outcome of entry.outcomes) {
    if (!keysAre(outcome, ['line', 'construct', 'group', 'outcome', 'hits'])) fail('Malformed Go outcome entry');
    const line = lineOf(outcome.line, limit);
    const key = [text(outcome.construct), text(outcome.group), text(outcome.outcome)].join('\0');
    if (keys.has(key)) fail('Duplicate Go outcome');
    keys.add(key);
    branches.push({from: line, to: line, covered: count(outcome.hits) > 0});
  }
  counts.lines[0] += lines.size;
  counts.lines[1] += [...lines.values()].filter(Boolean).length;
  counts.branches[0] += branches.length;
  counts.branches[1] += branches.filter(branch => branch.covered).length;
  return {lines, branches};
}

function counters(report, sourceDirectory, cwd, detail) {
  const root = realPath(sourceDirectory, cwd);
  const {modulePath, moduleRoot} = moduleOf(root);
  const sources = inventory(root, cwd);
  header(report, modulePath);
  const counts = emptyCounts();
  const seen = new Set();
  const inactive = [];
  for (const entry of report.files) {
    const {file, source, relative} = sourceOf(entry, moduleRoot, root, sources, seen, cwd);
    bind(entry, file, source, relative);
    if (entry.status === 'inactive') {
      inactive.push(`${relative} (${typeof entry.reason === 'string' ? entry.reason : 'no reason given'})`);
    } else if (entry.status !== 'measured' || Object.hasOwn(entry, 'reason')) {
      fail(`Unknown Go outcome file status: ${relative}`);
    } else {
      const measured = measure(entry, source.limit, counts);
      if (detail) detail.set(file, measured);
    }
  }
  const missing = [...sources.keys()].filter(file => !seen.has(file));
  if (missing.length) fail('Go application sources missing from the outcome report: ' + missing.sort().join(', '));
  if (inactive.length) {
    fail('Go application sources excluded from every declared build or never loaded; declare a build that includes them (goinstr -goos/-goarch/-tags and report -run): ' + inactive.sort().join(', '));
  }
  return counts;
}

module.exports = {counters};

'use strict';
const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const crypto = require('node:crypto');
const gate = require('./coverage-gate.cjs');
const plan = require('./coverage-plan.cjs');
const declared = require('./coverage-declared.cjs');

// The reports are real tools/goinstr output (Go 1.27.3) for test/fixtures/go-outcomes/app: `full` is the whole
// suite on the host and a windows build, `partial` runs three tests, `host-only` omits the windows build.
const FIXTURES = path.join(__dirname, '..', 'test', 'fixtures', 'go-outcomes');
const load = name => JSON.parse(fs.readFileSync(path.join(FIXTURES, `${name}.json`), 'utf8'));
const withTree = run => {
  const directory = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'clouseau-gooutcomes-')));
  try {
    fs.cpSync(path.join(FIXTURES, 'app'), directory, {recursive: true});
    return run(directory);
  } finally {fs.rmSync(directory, {recursive: true, force: true});}
};
const measure = (report, directory, detail) => gate.counters(report, directory, 'gooutcomes', directory, detail);
const rejects = (report, expected, directory) => assert.throws(() => measure(report, directory), expected);
const edit = (change, name = 'full') => {const report = load(name); change(report); return report;};
const entry = (report, file) => report.files.find(item => item.path === file);

test('outcome counts are measured: unloaded and unreached units stay unhit and a recovered panic is not inferred', () => withTree(directory => {
  assert.deepEqual(measure(load('full'), directory), {lines: [54, 48], branches: [46, 44]});
  assert.deepEqual(measure(load('partial'), directory), {lines: [54, 7], branches: [46, 2]});
  const detail = new Map();
  measure(load('full'), directory, detail);
  const decide = detail.get(path.join(directory, 'decide.go'));
  assert.equal(decide.lines.get(112), true);
  assert.equal(decide.lines.get(114), false);
  assert.equal(decide.lines.get(115), false);
  assert.ok(decide.branches.every(branch => branch.from === branch.to));
  assert.equal(detail.get(path.join(directory, 'unloaded', 'unloaded.go')).lines.get(6), false);
}));

test('a line is covered only when every statement starting on it ran', () => withTree(directory => {
  const report = load('full');
  const decide = entry(report, 'decide.go');
  decide.statements.push({line: 112, hits: 0});
  assert.deepEqual(measure(report, directory), {lines: [54, 47], branches: [46, 44]});
}));

test('every statement hit is validated, even after an unhit statement on the same line', () => withTree(directory => {
  const report = load('full');
  entry(report, 'decide.go').statements.push({line: 112, hits: 0}, {line: 112, hits: -1});
  rejects(report, /nonnegative safe integers/, directory);
}));

test('a file excluded from every declared build or never loaded is an explicit error, never branchless', () => withTree(directory => {
  rejects(load('host-only'), /excluded from every declared build.*platform_windows\.go \(excluded by build constraints/, directory);
  rejects(edit(report => {delete entry(report, 'platform_windows.go').reason;}, 'host-only'), /platform_windows\.go \(no reason given\)/, directory);
}));

test('missing, unknown, duplicate, stale and escaping files are rejected', () => withTree(directory => {
  rejects(edit(report => {report.files = report.files.filter(item => item.path !== 'unloaded/unloaded.go');}), /missing from the outcome report: .*unloaded\.go/, directory);
  rejects(edit(report => {report.files.push({...entry(report, 'decide.go'), path: 'extra.go'});}), /Unexpected Go application outcomes: extra\.go/, directory);
  rejects(edit(report => {report.files.push(entry(report, 'decide.go'));}), /Duplicate Go outcome entry: decide\.go/, directory);
  rejects(edit(report => {entry(report, 'decide.go').sha256 = crypto.createHash('sha256').update('other').digest('hex');}), /stale or from another source: decide\.go/, directory);
  rejects(edit(report => {entry(report, 'decide.go').lines += 1;}), /stale or from another source/, directory);
  fs.appendFileSync(path.join(directory, 'decide.go'), '// changed\n');
  rejects(load('full'), /stale or from another source/, directory);
}));

test('paths must be safe module-relative paths inside the source directory', () => withTree(directory => {
  for (const unsafe of ['/decide.go', 'a\\b.go', '../decide.go', 'unloaded//unloaded.go', './decide.go', '']) {
    rejects(edit(report => {entry(report, 'decide.go').path = unsafe;}), /Unsafe Go outcome path|nonempty strings/, directory);
  }
  rejects(edit(report => {entry(report, 'decide.go').path = 7;}), /nonempty strings/, directory);
  assert.throws(() => measure(load('full'), path.join(directory, 'unloaded')), /escapes the source directory: decide\.go/);
}));

test('the report header must be the exact supported schema for this module', () => withTree(directory => {
  rejects([], /Malformed Go outcome report/, directory);
  rejects(edit(report => {report.extra = 1;}), /Malformed Go outcome report/, directory);
  rejects(edit(report => {delete report.files;}), /Malformed Go outcome report/, directory);
  rejects(edit(report => {report.schema = 'other';}), /Unsupported Go outcome report schema/, directory);
  rejects(edit(report => {report.version = 2;}), /Unsupported Go outcome report schema/, directory);
  rejects(edit(report => {report.go_version = 'devel';}), /no Go version/, directory);
  rejects(edit(report => {report.go_version = 127;}), /no Go version/, directory);
  rejects(edit(report => {report.module = 'example.com/other';}), /another module/, directory);
  rejects(edit(report => {report.files = {};}), /Malformed Go outcome report/, directory);
  rejects(edit(report => {report.builds = [];}), /one to 16 declared builds/, directory);
  rejects(edit(report => {report.builds = 'host';}), /one to 16 declared builds/, directory);
  rejects(edit(report => {report.builds = Array(17).fill(report.builds[0]);}), /one to 16 declared builds/, directory);
  for (const broken of [null, {goos: 'linux', goarch: 'amd64'}, {goos: 'Linux', goarch: 'amd64', tags: []}, {goos: 'linux', goarch: 'x'.repeat(41), tags: []},
    {goos: 'linux', goarch: 'amd64', tags: 'a'}, {goos: 'linux', goarch: 'amd64', tags: [1]}, {goos: 'linux', goarch: 'amd64', tags: ['bad tag']}]) {
    rejects(edit(report => {report.builds = [broken];}), /requires goos, goarch and tags/, directory);
  }
  assert.deepEqual(measure(edit(report => {report.builds = [{goos: 'linux', goarch: 'amd64', tags: ['integration', 'go1.21']}];}), directory), {lines: [54, 48], branches: [46, 44]});
}));

test('file entries, statuses, statements and outcomes are strictly shaped', () => withTree(directory => {
  rejects(edit(report => {report.files[0] = null;}), /Malformed Go outcome file entry/, directory);
  rejects(edit(report => {report.files[0].extra = 1;}), /Malformed Go outcome file entry/, directory);
  rejects(edit(report => {entry(report, 'decide.go').status = 'covered';}), /Unknown Go outcome file status: decide\.go/, directory);
  rejects(edit(report => {entry(report, 'decide.go').reason = 'why';}), /Unknown Go outcome file status/, directory);
  rejects(edit(report => {entry(report, 'decide.go').statements = {};}), /Malformed Go outcome file entry/, directory);
  rejects(edit(report => {entry(report, 'decide.go').outcomes = null;}), /Malformed Go outcome file entry/, directory);
  rejects(edit(report => {entry(report, 'decide.go').statements[0] = {line: 5};}), /Malformed Go statement entry/, directory);
  rejects(edit(report => {entry(report, 'decide.go').outcomes[0] = {line: 5};}), /Malformed Go outcome entry/, directory);
  for (const line of [0, 127, 1.5, '5', -1]) {
    rejects(edit(report => {entry(report, 'decide.go').statements[0].line = line;}), /beyond the source file|nonnegative safe integers/, directory);
  }
  for (const hits of [-1, 1.5, '1', 2 ** 60]) {
    rejects(edit(report => {entry(report, 'decide.go').statements[0].hits = hits;}), /nonnegative safe integers/, directory);
    rejects(edit(report => {entry(report, 'decide.go').outcomes[0].hits = hits;}), /nonnegative safe integers/, directory);
  }
  for (const field of ['construct', 'group', 'outcome']) {
    for (const value of ['', 7, 'x'.repeat(300)]) {
