// Runs the real tools/goinstr program (Go is required; the test is skipped without it) and checks that what it
// writes is what the committed reports contain, which src/coverage-gooutcomes.test.cjs reads without Go.
// The per-outcome-class proofs live in tools/goinstr/main_test.go, which this test also runs.
const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const {spawnSync} = require('node:child_process');
const gate = require('./coverage-gate.cjs');

const ROOT = path.join(__dirname, '..');
const TOOL = path.join(ROOT, 'tools', 'goinstr');
const FIXTURES = path.join(ROOT, 'test', 'fixtures', 'go-outcomes');
// The verify job has a fixed ten-minute budget and runs this suite three times, so Go executes once, in the coverage
// verification (scripts/verify-coverage sets NODE_V8_COVERAGE). The adapter tests read the same committed real reports
// without Go in every pass.
const hasGo = spawnSync('go', ['version']).status === 0 && Boolean(process.env.NODE_V8_COVERAGE);
const go = (cwd, args) => {
  const result = spawnSync('go', args, {cwd, encoding: 'utf8'});
  assert.equal(result.status, 0, `go ${args.join(' ')}\n${result.stdout}${result.stderr}`);
  return result.stdout;
};

test('goinstr produces the committed report for the fixture module and the gate measures it', {skip: !hasGo}, () => {
  const directory = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'clouseau-goinstr-')));
  try {
    const app = path.join(directory, 'app');
    fs.cpSync(path.join(FIXTURES, 'app'), app, {recursive: true});
    const tool = path.join(directory, 'goinstr');
    go(TOOL, ['build', '-o', tool, '.']);
    const run = args => {
      const result = spawnSync(tool, args, {cwd: app, encoding: 'utf8'});
      assert.equal(result.status, 0, result.stderr);
    };
    const host = path.join(directory, 'host');
    const windows = path.join(directory, 'windows');
    run(['instrument', '-module', '.', '-work', host]);
    run(['instrument', '-module', '.', '-work', windows, '-goos', 'windows', '-goarch', 'amd64']);
    go(app, ['test', '-count=1', `-overlay=${path.join(host, 'overlay.json')}`, './...']);
    const report = path.join(directory, 'report.json');
    run(['report', '-out', report, '-run', host, '-run', windows]);
    const produced = JSON.parse(fs.readFileSync(report, 'utf8'));
    const committed = JSON.parse(fs.readFileSync(path.join(FIXTURES, 'full.json'), 'utf8'));
    assert.deepEqual({...produced, go_version: null, builds: null}, {...committed, go_version: null, builds: null});
    assert.deepEqual(gate.counters(produced, app, 'gooutcomes', app), {lines: [54, 48], branches: [46, 44]});
  } finally {fs.rmSync(directory, {recursive: true, force: true});}
});

test('the goinstr program passes its own tests, vet and formatting', {skip: !hasGo}, () => {
  go(TOOL, ['vet', './...']);
  go(TOOL, ['test', '-count=1', './...']);
  const formatted = spawnSync('gofmt', ['-l', TOOL], {encoding: 'utf8'});
  assert.equal(formatted.stdout, '');
});

package app

// Sign has an if with no else: the false outcome is implicit.
func Sign(n int) string {
	if n < 0 {
		return "negative"
	} else if n == 0 {
		return "zero"
	}
	return "positive"
}

// Both and Either use short-circuit operands that are separate outcomes.
func Both(a, b bool) bool { return a && b }

func Either(a, b bool) bool {
	if a || b {
		return true
	}
	return false
}

type Flag bool

// On decides over a named boolean type.
func (f Flag) On(g Flag) Flag { return f && g }

// Grade is a switch without default: no match is an outcome.
func Grade(n int) string {
	switch {
	case n >= 90:
		return "A"
	case n >= 80:
		return "B"
	}
	return "?"
}

// Kind is a type switch without default.
func Kind(v any) string {
	switch v.(type) {
	case int:
		return "int"
	case string:
		return "string"
	}
	return "other"
}

// Named is a switch with an explicit default.
func Named(n int) string {
	switch n {
	case 1:
		return "one"
	default:
		return "many"
	}
}

// Total ranges over a slice: an empty slice never enters the body.
func Total(values []int) int {
	sum := 0
	for _, value := range values {
		sum += value
	}
	return sum
}

// Count is a conditional loop.
func Count(limit int) int {
	steps := 0
	for steps < limit {
		steps++
	}
	return steps
}

// Skip uses a labeled loop with continue.
func Skip(rows [][]int) int {
	kept := 0
outer:
	for _, row := range rows {
		for _, value := range row {
			if value < 0 {
				continue outer
			}
			kept++
		}
	}
	return kept
}

// Receive selects among channels, with and without default.
func Receive(ready chan int, wait bool) int {
	if wait {
		select {
		case value := <-ready:
			return value
		}
	}
	select {
	case value := <-ready:
		return value
	default:
		return -1
	}
}

// Recovered panics after the first assignment and recovers; the second assignment never runs.
func Recovered() (result int) {
	defer func() { _ = recover() }()
	result = 1
	explode()
	result = 2
	return result
}

func explode() { panic("boom") }

// Early returns before its last statement.
func Early(stop bool) int {
	if stop {
		return 0
	}
	return 1
}

