// Command goinstr measures Go executable lines and branch outcomes by rewriting application sources into an
// overlay (go test -overlay) whose counters write each taken outcome to disk at the moment it is taken.
//
//	goinstr instrument -module DIR -work DIR [-goos OS] [-goarch ARCH] [-tags a,b]
//	goinstr report -out FILE -run WORKDIR [-run WORKDIR ...]
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

const (
	schema       = "clouseau-go-outcomes"
	manifestName = "manifest.json"
	coverFile    = "zz_clouseau_cover.go"
)

type Build struct {
	GOOS   string   `json:"goos"`
	GOARCH string   `json:"goarch"`
	Tags   []string `json:"tags"`
}

type packageHits struct {
	Index int `json:"index"`
	Count int `json:"count"`
}

type fileEntry struct {
	Path    string `json:"path"`
	SHA256  string `json:"sha256"`
	Lines   int    `json:"lines"`
	Status  string `json:"status"`
	Reason  string `json:"reason,omitempty"`
	Package int    `json:"package"`
	Units   []Unit `json:"units"`
}

type manifest struct {
	Schema    string        `json:"schema"`
	GoVersion string        `json:"go_version"`
	Module    string        `json:"module"`
	Build     Build         `json:"build"`
	Packages  []packageHits `json:"packages"`
	Files     []fileEntry   `json:"files"`
}

type listedPackage struct {
	Dir            string
	ImportPath     string
	Name           string
	GoFiles        []string
	CgoFiles       []string
	IgnoredGoFiles []string
	Error          *struct{ Err string }
	Module         *struct {
		Path      string
		Dir       string
		GoVersion string
	}
}

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, "goinstr:", err)
		os.Exit(1)
	}
}

func run(args []string) error {
	if len(args) == 0 {
		return errors.New("usage: goinstr instrument|report ...")
	}
	switch args[0] {
	case "instrument":
		return runInstrument(args[1:])
	case "report":
		return runReport(args[1:])
	}
	return fmt.Errorf("unknown command %q", args[0])
}

func goOutput(dir string, env []string, args ...string) ([]byte, error) {
	command := exec.Command("go", args...)
	command.Dir = dir
	command.Env = append(os.Environ(), env...)
	var stderr strings.Builder
	command.Stderr = &stderr
	out, err := command.Output()
	if err != nil {
		return nil, fmt.Errorf("go %s: %v: %s", strings.Join(args, " "), err, strings.TrimSpace(stderr.String()))
	}
	return out, nil
}

func goEnv(dir, name string, env []string) (string, error) {
	out, err := goOutput(dir, env, "env", name)
	return strings.TrimSpace(string(out)), err
}

func versionAtLeast(version string, major, minor int) bool {
	parts := strings.Split(version, ".")
	if len(parts) < 2 {
		return false
	}
	a, errA := strconv.Atoi(parts[0])
	b, errB := strconv.Atoi(parts[1])
	return errA == nil && errB == nil && (a > major || a == major && b >= minor)
}

var excludedDirectories = map[string]bool{"vendor": true, "testdata": true, "node_modules": true}

// inventory lists every production .go file of the module, with the same exclusions the Node adapter applies.
func inventory(root string) ([]string, error) {
	var files []string
	var walk func(directory string) error
	walk = func(directory string) error {
		entries, err := os.ReadDir(directory)
		if err != nil {
			return err
		}
		for _, entry := range entries {
			name := entry.Name()
			path := filepath.Join(directory, name)
			switch {
			case entry.Type()&os.ModeSymlink != 0:
				if strings.HasSuffix(name, ".go") {
					return fmt.Errorf("symbolic Go source: %s", path)
				}
			case entry.IsDir():
				if _, nested := os.Stat(filepath.Join(path, "go.mod")); strings.HasPrefix(name, ".") || strings.HasPrefix(name, "_") ||
					excludedDirectories[name] || nested == nil {
					continue
				}
				if err := walk(path); err != nil {
					return err
				}
			case strings.HasSuffix(name, ".go") && !strings.HasSuffix(name, "_test.go"):
				files = append(files, path)
			}
		}
		return nil
	}
	return files, walk(root)
}

func runInstrument(args []string) (failure error) {
	flags := flag.NewFlagSet("instrument", flag.ContinueOnError)
	moduleFlag := flags.String("module", ".", "module root")
	workFlag := flags.String("work", "", "work directory for the overlay, manifest and hits")
	goos := flags.String("goos", "", "GOOS (default: go env)")
	goarch := flags.String("goarch", "", "GOARCH (default: go env)")
	tagsFlag := flags.String("tags", "", "comma-separated build tags")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *workFlag == "" {
		return errors.New("-work is required")
	}
	logical, err := filepath.Abs(*moduleFlag)
	if err != nil {
		return err
	}
	root, err := filepath.EvalSymlinks(logical)
	if err != nil {
		return err
	}
	work, err := filepath.Abs(*workFlag)
	if err != nil {
		return err
	}
	if info, err := os.Lstat(work); err == nil && !info.IsDir() {
		return fmt.Errorf("work path %s exists and is not a directory", work)
	}
	if entries, err := os.ReadDir(work); err == nil && len(entries) > 0 {
		if !ownDirectory(work, entries) {
			return fmt.Errorf("work directory %s is not empty and not a goinstr directory", work)
		}
		if err := os.RemoveAll(work); err != nil {
			return err
		}
	}
	defer func() {
		if failure != nil {
			os.RemoveAll(work)
		}
	}()
	var env []string
	if *goos != "" {
		env = append(env, "GOOS="+*goos)
	}
	if *goarch != "" {
		env = append(env, "GOARCH="+*goarch)
	}
	build := Build{Tags: []string{}}
	if *tagsFlag != "" {
		build.Tags = strings.Split(*tagsFlag, ",")
		sort.Strings(build.Tags)
	}
	if build.GOOS, err = goEnv(root, "GOOS", env); err != nil {
		return err
	}
	if build.GOARCH, err = goEnv(root, "GOARCH", env); err != nil {
		return err
	}
	version, err := goEnv(root, "GOVERSION", env)
	if err != nil {
		return err
	}
	listArgs := []string{"list", "-e", "-json"}
	if len(build.Tags) > 0 {
		listArgs = append(listArgs, "-tags="+strings.Join(build.Tags, ","))
	}
	listed, err := goOutput(root, env, append(listArgs, "./...")...)
	if err != nil {
		return err
	}
	packages, err := decodePackages(listed)
	if err != nil {
		return err
	}
	m := &manifest{Schema: schema, GoVersion: version, Build: build}
	overlay := map[string]string{}
	ignored := map[string]bool{}
	sort.Slice(packages, func(i, j int) bool { return packages[i].ImportPath < packages[j].ImportPath })
	for _, pkg := range packages {
		if pkg.Module == nil || pkg.Module.Dir != root {
			return fmt.Errorf("package %s is outside the module at %s", pkg.ImportPath, root)
		}
		if m.Module != "" && m.Module != pkg.Module.Path {
			return errors.New("packages from more than one module")
		}
		m.Module = pkg.Module.Path
		if !versionAtLeast(pkg.Module.GoVersion, 1, 18) {
			return fmt.Errorf("go.mod must declare go 1.18 or newer (found %q): the counters use generics", pkg.Module.GoVersion)
		}
		if len(pkg.CgoFiles) > 0 {
			return fmt.Errorf("package %s uses cgo, which is not supported", pkg.ImportPath)
		}
		if pkg.Error != nil && !(len(pkg.GoFiles) == 0 && len(pkg.IgnoredGoFiles) > 0) {
			return fmt.Errorf("package %s: %s", pkg.ImportPath, strings.TrimSpace(pkg.Error.Err))
		}
		for _, name := range pkg.IgnoredGoFiles {
			ignored[filepath.Join(pkg.Dir, name)] = true
		}
		if len(pkg.GoFiles) > 0 {
			if err := instrumentPackage(m, work, overlay, pkg, [2]string{root, logical}); err != nil {
				return err
			}
		}
	}
	files, err := inventory(root)
	if err != nil {
		return err
	}
	have := map[string]bool{}
	for _, entry := range m.Files {
		have[entry.Path] = true
	}
	for _, file := range files {
		relative, _ := filepath.Rel(root, file)
		relative = filepath.ToSlash(relative)
		if have[relative] {
			continue
		}
		reason := "not part of any package loaded by go list"
		if ignored[file] {
			reason = fmt.Sprintf("excluded by build constraints for goos=%s goarch=%s tags=[%s]", build.GOOS, build.GOARCH, strings.Join(build.Tags, ","))
		}
		entry, err := describe(root, relative)
		if err != nil {
			return err
		}
		entry.Status, entry.Reason, entry.Units = "inactive", reason, []Unit{}
		m.Files = append(m.Files, entry)
	}
	sort.Slice(m.Files, func(i, j int) bool { return m.Files[i].Path < m.Files[j].Path })
	if err := os.MkdirAll(filepath.Join(work, "hits"), 0o755); err != nil {
		return err
	}
	if err := writeJSON(filepath.Join(work, "overlay.json"), map[string]any{"Replace": overlay}); err != nil {
		return err
	}
	return writeJSON(filepath.Join(work, manifestName), m)
}

func decodePackages(data []byte) ([]listedPackage, error) {
	decoder := json.NewDecoder(strings.NewReader(string(data)))
	var packages []listedPackage
	for decoder.More() {
		var pkg listedPackage
		if err := decoder.Decode(&pkg); err != nil {
			return nil, err
		}
		packages = append(packages, pkg)
	}
	if len(packages) == 0 {
		return nil, errors.New("go list found no packages")
	}
	return packages, nil
}

func describe(root, relative string) (fileEntry, error) {
	data, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(relative)))
	if err != nil {
		return fileEntry{}, err
	}
	sum := sha256.Sum256(data)
	lines := strings.Count(string(data), "\n")
	if len(data) > 0 && data[len(data)-1] != '\n' {
		lines++
	}
	return fileEntry{Path: relative, SHA256: hex.EncodeToString(sum[:]), Lines: lines}, nil
}

func instrumentPackage(m *manifest, work string, overlay map[string]string, pkg listedPackage, roots [2]string) error {
	index := len(m.Packages)
	next := 0
	root := pkg.Module.Dir
	names := append([]string(nil), pkg.GoFiles...)
	sort.Strings(names)
	for _, name := range names {
		path := filepath.Join(pkg.Dir, name)
		relative, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		relative = filepath.ToSlash(relative)
		entry, err := describe(root, relative)
		if err != nil {
			return err
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		out, units, err := instrument(relative, data, &next)
		if err != nil {
			return err
		}
		target := filepath.Join(work, "src", fmt.Sprintf("%d-%s", index, name))
		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(target, out, 0o644); err != nil {
			return err
		}
		overlayAdd(overlay, path, target, roots)
		entry.Status, entry.Package, entry.Units = "measured", index, units
		m.Files = append(m.Files, entry)
	}
	cover := filepath.Join(pkg.Dir, coverFile)
	if _, err := os.Stat(cover); err == nil {
		return fmt.Errorf("%s already exists", cover)
	}
	target := filepath.Join(work, "src", fmt.Sprintf("%d-%s", index, coverFile))
	hits := filepath.Join(work, "hits", fmt.Sprintf("%d.hit", index))
	if err := os.WriteFile(target, []byte(coverSource(pkg.Name, hits, next)), 0o644); err != nil {
		return err
	}
	overlayAdd(overlay, cover, target, roots)
	m.Packages = append(m.Packages, packageHits{Index: index, Count: next})
	return nil
}

// coverSource is the per-package runtime. A first hit of a counter is written at once with pwrite, so a taken
// outcome survives os.Exit, a crash and a recovered panic, and several test binaries may share one file.
func coverSource(name, hits string, count int) string {
	size := count
	if size == 0 {
		size = 1
	}
	return fmt.Sprintf(`// Code generated by clouseau goinstr. DO NOT EDIT.

package %s

import (
	clouseauos "os"
	clouseausync "sync"
	clouseauatomic "sync/atomic"
)

const clouseauHitsPath = %q

var (
	clouseauSeen [%d]uint32
	clouseauMu   clouseausync.Mutex
	clouseauFile *clouseauos.File
)

func clouseauHit(id int) {
	if clouseauatomic.CompareAndSwapUint32(&clouseauSeen[id], 0, 1) && !clouseauRecord(id) {
		clouseauatomic.StoreUint32(&clouseauSeen[id], 0)
	}
}

func clouseauRecord(id int) bool {
	clouseauMu.Lock()
	defer clouseauMu.Unlock()
	if clouseauFile == nil {
		file, err := clouseauos.OpenFile(clouseauHitsPath, clouseauos.O_WRONLY|clouseauos.O_CREATE, 0o644)
		if err != nil {
			clouseauos.Stderr.WriteString("clouseau goinstr: " + err.Error() + "\n")
			return false
		}
		clouseauFile = file
	}
	if _, err := clouseauFile.WriteAt([]byte{1}, int64(id)); err != nil {
		clouseauos.Stderr.WriteString("clouseau goinstr: " + err.Error() + "\n")
		return false
	}
	return true
}

func clouseauB[T ~bool](taken, other int, value T) T {
	if value {
		clouseauHit(taken)
	} else {
		clouseauHit(other)
	}
	return value
}
`, name, hits, size)
}

func writeJSON(path string, value any) error {
	data, err := json.MarshalIndent(value, "", " ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, append(data, '\n'), 0o644)
}

// overlayAdd maps a source to its replacement under the module path go list reports and under the path the shell may
// use for the same directory (a symbolic link such as macOS /var), because go matches the overlay by the path it sees.
func overlayAdd(overlay map[string]string, path, target string, roots [2]string) {
	overlay[path] = target
	if roots[0] != roots[1] {
		if relative, err := filepath.Rel(roots[0], path); err == nil {
			overlay[filepath.Join(roots[1], relative)] = target
		}
	}
}

// ownDirectory is true only for a directory goinstr wrote: its manifest carries the goinstr schema and nothing else is in it.
func ownDirectory(work string, entries []os.DirEntry) bool {
	data, err := os.ReadFile(filepath.Join(work, manifestName))
	var m manifest
	if err != nil || json.Unmarshal(data, &m) != nil || m.Schema != schema {
		return false
	}
	for _, entry := range entries {
		switch entry.Name() {
		case manifestName, "overlay.json", "src", "hits":
		default:
			return false
		}
	}
	return true
}

package main

import (
	"encoding/json"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

const fixtureApp = "../../test/fixtures/go-outcomes/app"

func copyTree(t *testing.T, from string) string {
	t.Helper()
	to := t.TempDir()
	err := filepath.WalkDir(from, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		relative, _ := filepath.Rel(from, path)
		if entry.IsDir() {
			return os.MkdirAll(filepath.Join(to, relative), 0o755)
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		return os.WriteFile(filepath.Join(to, relative), data, 0o644)
	})
	if err != nil {
		t.Fatal(err)
	}
	return to
}

func command(t *testing.T, dir string, name string, args ...string) string {
	t.Helper()
	c := exec.Command(name, args...)
	c.Dir = dir
	out, err := c.CombinedOutput()
	if err != nil {
		t.Fatalf("%s %v: %v\n%s", name, args, err, out)
	}
	return string(out)
}

// measure instruments a copy of the module, runs the selected tests against the overlay and returns the report.
func measure(t *testing.T, module string, pattern string, extra ...string) report {
	t.Helper()
	work := filepath.Join(t.TempDir(), "work")
	if err := run(append([]string{"instrument", "-module", module, "-work", work}, extra...)); err != nil {
		t.Fatal(err)
	}
	command(t, module, "go", "test", "-count=1", "-run", pattern, "-overlay="+filepath.Join(work, "overlay.json"), "./...")
	return build(t, filepath.Join(t.TempDir(), "report.json"), work)
}

func build(t *testing.T, out string, works ...string) report {
	t.Helper()
	args := []string{"report", "-out", out}
	for _, work := range works {
		args = append(args, "-run", work)
	}
	if err := run(args); err != nil {
		t.Fatal(err)
	}
	var result report
	data, err := os.ReadFile(out)
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, &result); err != nil {
		t.Fatal(err)
	}
	return result
}

func file(t *testing.T, r report, path string) reportFile {
	t.Helper()
	for _, f := range r.Files {
		if f.Path == path {
			return f
		}
	}
	t.Fatalf("%s missing from the report", path)
	return reportFile{}
}

func outcomes(t *testing.T, r report, line int, construct, outcome string) []int {
	t.Helper()
	var hits []int
	for _, o := range file(t, r, "decide.go").Outcomes {
		if o.Line == line && o.Construct == construct && o.Outcome == outcome {
			hits = append(hits, o.Hits)
		}
	}
	if len(hits) == 0 {
		t.Fatalf("no %s %s outcome on line %d", construct, outcome, line)
	}
	return hits
}

func statement(t *testing.T, r report, line int) int {
	t.Helper()
	total, count := 0, 0
	for _, s := range file(t, r, "decide.go").Statements {
		if s.Line == line {
			total, count = total+s.Hits, count+1
		}
	}
	if count == 0 {
		t.Fatalf("no statement on line %d", line)
	}
	return total
}

func expect(t *testing.T, what string, got []int, want ...int) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("%s: got %v want %v", what, got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("%s: got %v want %v", what, got, want)
		}
	}
}

func TestImplicitFalseAndElseIf(t *testing.T) {
	module := copyTree(t, fixtureApp)
	negative := measure(t, module, "^TestSignNegative$")
	expect(t, "if true", outcomes(t, negative, 5, "if", "true"), 1)
	expect(t, "if false", outcomes(t, negative, 5, "if", "false"), 0)
	expect(t, "else-if untouched", outcomes(t, negative, 7, "if", "true"), 0)
	positive := measure(t, module, "^TestSignPositive$")
	expect(t, "implicit false of the else-if", outcomes(t, positive, 7, "if", "false"), 1)
	expect(t, "else-if true", outcomes(t, positive, 7, "if", "true"), 0)
}

func TestShortCircuitOperandsAreSeparateOutcomes(t *testing.T) {
	module := copyTree(t, fixtureApp)
	first := measure(t, module, "^TestBothFirstFalse$")
	hit := 0
	for _, o := range file(t, first, "decide.go").Outcomes {
		if o.Line == 14 && o.Construct == "operand" {
			hit += o.Hits
			if o.Hits == 1 && o.Outcome != "false" {
				t.Fatalf("the first operand should only be false: %+v", o)
			}
		}
	}
	if hit != 1 {
		t.Fatalf("a false first operand must not record the second operand, got %d hits", hit)
	}
	all := measure(t, module, "^TestBoth")
	for _, o := range file(t, all, "decide.go").Outcomes {
		if o.Line == 14 && o.Construct == "operand" && o.Hits != 1 {
			t.Fatalf("every operand outcome should be taken: %+v", o)
		}
	}
}

func TestSwitchTypeSwitchAndSelectOutcomes(t *testing.T) {
	module := copyTree(t, fixtureApp)
	matched := measure(t, module, "^TestGradeA$|^TestKindInt$|^TestNamedOne$|^TestReceiveDefault$")
	expect(t, "switch no-match", outcomes(t, matched, 30, "switch", "no-match"), 0)
	expect(t, "typeswitch no-match", outcomes(t, matched, 41, "typeswitch", "no-match"), 0)
	expect(t, "default", outcomes(t, matched, 55, "switch", "default"), 0)
	expect(t, "select case not ready", outcomes(t, matched, 102, "select", "case@102:2"), 0)
	expect(t, "select default", outcomes(t, matched, 104, "select", "default"), 1)
	unmatched := measure(t, module, "^TestGradeNoMatch$|^TestKindNoMatch$|^TestNamedDefault$")
	expect(t, "switch no-match", outcomes(t, unmatched, 30, "switch", "no-match"), 1)
	expect(t, "typeswitch no-match", outcomes(t, unmatched, 41, "typeswitch", "no-match"), 1)
	expect(t, "default", outcomes(t, unmatched, 55, "switch", "default"), 1)
}

func TestLoopZeroEntry(t *testing.T) {
	module := copyTree(t, fixtureApp)
	entered := measure(t, module, "^TestTotalNonEmpty$|^TestCountLoop$")
	expect(t, "range enter", outcomes(t, entered, 63, "range", "enter"), 1)
	expect(t, "range zero-entry", outcomes(t, entered, 63, "range", "zero-entry"), 0)
	expect(t, "for entered", outcomes(t, entered, 72, "for", "true"), 1)
	expect(t, "for exit", outcomes(t, entered, 72, "for", "false"), 1)
	expect(t, "for zero-entry", outcomes(t, entered, 72, "for", "zero-entry"), 0)
	empty := measure(t, module, "^TestTotalEmpty$|^TestCountZero$")
	expect(t, "range enter", outcomes(t, empty, 63, "range", "enter"), 0)
	expect(t, "range zero-entry", outcomes(t, empty, 63, "range", "zero-entry"), 1)
	expect(t, "for entered", outcomes(t, empty, 72, "for", "true"), 0)
	expect(t, "for zero-entry", outcomes(t, empty, 72, "for", "zero-entry"), 1)
}

func TestEarlyExitLeavesLaterStatementsUnhit(t *testing.T) {
	module := copyTree(t, fixtureApp)
	stopped := measure(t, module, "^TestEarlyStop$")
	if statement(t, stopped, 123) != 1 || statement(t, stopped, 125) != 0 {
		t.Fatal("only the early return should have run")
	}
	expect(t, "if false", outcomes(t, stopped, 122, "if", "false"), 0)
}

func TestRecoveredPanicIsNotInferred(t *testing.T) {
	module := copyTree(t, fixtureApp)
	recovered := measure(t, module, "^TestRecovered$")
	if statement(t, recovered, 112) != 1 || statement(t, recovered, 113) != 1 {
		t.Fatal("the statements before the panic ran")
	}
	if statement(t, recovered, 114) != 0 || statement(t, recovered, 115) != 0 {
		t.Fatal("the statements after the recovered panic did not run")
	}
	// Go's own profile reports the whole block, including the statement that never ran, as covered.
	profile := filepath.Join(t.TempDir(), "cover.out")
	command(t, module, "go", "test", "-count=1", "-run", "^TestRecovered$", "-coverprofile="+profile, ".")
	data, _ := os.ReadFile(profile)
	if !strings.Contains(string(data), "decide.go:112.2,115.15 4 1") {
		t.Fatalf("expected a standard profile block for Recovered:\n%s", data)
	}
}

func TestFullSuiteLeavesOnlyUnreachedUnitsAndFlagsUnloadedAndInactiveFiles(t *testing.T) {
	module := copyTree(t, fixtureApp)
	full := measure(t, module, ".")
	for _, o := range file(t, full, "decide.go").Outcomes {
		if o.Hits != 1 {
			t.Fatalf("every outcome should be taken by the full suite: %+v", o)
		}
	}
	unloaded := file(t, full, "unloaded/unloaded.go")
	if unloaded.Status != "measured" || len(unloaded.Statements) == 0 || len(unloaded.Outcomes) == 0 {
		t.Fatalf("an unloaded package must be inventoried: %+v", unloaded)
	}
	for _, s := range unloaded.Statements {
		if s.Hits != 0 {
			t.Fatal("an unloaded package has no hits")
		}
	}
	windows := file(t, full, "platform_windows.go")
	if windows.Status != "inactive" || !strings.Contains(windows.Reason, "build constraints") {
		t.Fatalf("a build-constrained file is explicit: %+v", windows)
	}
}

func TestBuildsAndShardsAreAggregated(t *testing.T) {
	module := copyTree(t, fixtureApp)
	temporary := t.TempDir()
	one, two, win := filepath.Join(temporary, "one"), filepath.Join(temporary, "two"), filepath.Join(temporary, "win")
	for _, work := range []string{one, two} {
		if err := run([]string{"instrument", "-module", module, "-work", work}); err != nil {
			t.Fatal(err)
		}
	}
	if err := run([]string{"instrument", "-module", module, "-work", win, "-goos", "windows", "-goarch", "amd64"}); err != nil {
		t.Fatal(err)
	}
	command(t, module, "go", "test", "-count=1", "-run", "^TestSignNegative$", "-overlay="+filepath.Join(one, "overlay.json"), ".")
	command(t, module, "go", "test", "-count=1", "-run", "^TestSignZero$", "-overlay="+filepath.Join(two, "overlay.json"), ".")
	cross := exec.Command("go", "build", "-overlay="+filepath.Join(win, "overlay.json"), "./...")
	cross.Dir = module
	cross.Env = append(os.Environ(), "GOOS=windows", "GOARCH=amd64")
	if out, err := cross.CombinedOutput(); err != nil {
		t.Fatalf("the windows overlay must compile: %v\n%s", err, out)
	}
	merged := build(t, filepath.Join(temporary, "r.json"), one, two, win)
	expect(t, "first shard", outcomes(t, merged, 5, "if", "true"), 1)
	expect(t, "second shard", outcomes(t, merged, 7, "if", "true"), 1)
	if len(merged.Builds) != 3 {
		t.Fatalf("every build is recorded: %+v", merged.Builds)
	}
	windows := file(t, merged, "platform_windows.go")
	if windows.Status != "measured" || len(windows.Statements) == 0 || windows.Statements[0].Hits != 0 {
		t.Fatalf("a file active in one declared build is measured: %+v", windows)
	}
}

func TestUnsupportedAndInvalidInputsFail(t *testing.T) {
	module := copyTree(t, fixtureApp)
	work := filepath.Join(t.TempDir(), "work")
	if err := os.WriteFile(filepath.Join(module, "init.go"), []byte("package app\n\nvar ready = Both(true, true) && Both(true, false)\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := run([]string{"instrument", "-module", module, "-work", work}); err == nil || !strings.Contains(err.Error(), "outside a function body") {
		t.Fatalf("a package-level short circuit is an explicit error: %v", err)
	}
	os.Remove(filepath.Join(module, "init.go"))
	old := filepath.Join(module, "go.mod")
	data, _ := os.ReadFile(old)
	os.WriteFile(old, []byte(strings.Replace(string(data), "go 1.21", "go 1.17", 1)), 0o644)
	if err := run([]string{"instrument", "-module", module, "-work", work}); err == nil || !strings.Contains(err.Error(), "go 1.18") {
		t.Fatalf("an old go.mod is an explicit error: %v", err)
	}
	os.WriteFile(old, data, 0o644)
	if err := os.MkdirAll(work, 0o755); err != nil {
		t.Fatal(err)
	}
	os.WriteFile(filepath.Join(work, "keep.txt"), []byte("x"), 0o644)
	if err := run([]string{"instrument", "-module", module, "-work", work}); err == nil || !strings.Contains(err.Error(), "not empty") {
		t.Fatalf("a foreign work directory is never removed: %v", err)
	}
	plain := filepath.Join(t.TempDir(), "plain")
	os.WriteFile(plain, []byte("x"), 0o644)
	if err := run([]string{"instrument", "-module", module, "-work", plain}); err == nil || !strings.Contains(err.Error(), "not a directory") {
		t.Fatalf("a regular file is never a work directory: %v", err)
	}
	if _, err := os.Stat(plain); err != nil {
		t.Fatal("the regular file was removed")
	}
	// A directory that merely has a manifest.json of its own is never removed either.
	os.WriteFile(filepath.Join(work, "manifest.json"), []byte(`{"schema":"other"}`), 0o644)
	if err := run([]string{"instrument", "-module", module, "-work", work}); err == nil {
		t.Fatal("a foreign manifest must not authorize removal")
	}
	if _, err := os.Stat(filepath.Join(work, "keep.txt")); err != nil {
		t.Fatal("the foreign directory was touched")
	}
	os.Remove(filepath.Join(work, "keep.txt"))
	os.Remove(filepath.Join(work, "manifest.json"))
	if err := run([]string{"instrument", "-module", module, "-work", work}); err != nil {
		t.Fatal(err)
	}
	if err := run([]string{"instrument", "-module", module, "-work", work}); err != nil {
		t.Fatalf("a goinstr directory is reusable: %v", err)
	}
	for _, args := range [][]string{{}, {"nothing"}, {"report"}, {"instrument"}} {
		if run(args) == nil {
			t.Fatalf("%v should fail", args)
		}
	}
}

package main

import (
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type statementHit struct {
	Line int `json:"line"`
	Hits int `json:"hits"`
}

type outcomeHit struct {
	Line      int    `json:"line"`
	Construct string `json:"construct"`
	Group     string `json:"group"`
	Outcome   string `json:"outcome"`
	Hits      int    `json:"hits"`
}

type reportFile struct {
	Path       string         `json:"path"`
	SHA256     string         `json:"sha256"`
	Lines      int            `json:"lines"`
	Status     string         `json:"status"`
	Reason     string         `json:"reason,omitempty"`
	Statements []statementHit `json:"statements"`
	Outcomes   []outcomeHit   `json:"outcomes"`
}

type report struct {
	Schema    string       `json:"schema"`
	Version   int          `json:"version"`
	GoVersion string       `json:"go_version"`
	Module    string       `json:"module"`
	Builds    []Build      `json:"builds"`
	Files     []reportFile `json:"files"`
}

type runFlags []string

func (r *runFlags) String() string     { return strings.Join(*r, ",") }
func (r *runFlags) Set(v string) error { *r = append(*r, v); return nil }

func runReport(args []string) error {
	flags := flag.NewFlagSet("report", flag.ContinueOnError)
	out := flags.String("out", "", "report file to write")
	var runs runFlags
	flags.Var(&runs, "run", "work directory of one instrumented run (repeat for builds or shards)")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *out == "" || len(runs) == 0 {
		return errors.New("-out and at least one -run are required")
	}
	result := report{Schema: schema, Version: 1}
	byPath := map[string]*reportFile{}
	for _, work := range runs {
		data, err := os.ReadFile(filepath.Join(work, manifestName))
		if err != nil {
			return err
		}
		var m manifest
		if err := json.Unmarshal(data, &m); err != nil || m.Schema != schema {
			return fmt.Errorf("%s is not a goinstr manifest", work)
		}
		if result.Module != "" && (result.Module != m.Module || result.GoVersion != m.GoVersion) {
			return errors.New("runs differ in module or Go version")
		}
		result.Module, result.GoVersion = m.Module, m.GoVersion
		result.Builds = append(result.Builds, m.Build)
		hits := map[int][]byte{}
		for _, p := range m.Packages {
			bytes, err := os.ReadFile(filepath.Join(work, "hits", fmt.Sprintf("%d.hit", p.Index)))
			if err != nil && !os.IsNotExist(err) {
				return err
			}
			hits[p.Index] = bytes
		}
		for _, entry := range m.Files {
			if err := merge(byPath, entry, hits[entry.Package]); err != nil {
				return err
			}
		}
	}
	for _, file := range byPath {
		result.Files = append(result.Files, *file)
	}
	sort.Slice(result.Files, func(i, j int) bool { return result.Files[i].Path < result.Files[j].Path })
	data, err := json.Marshal(result)
	if err != nil {
		return err
	}
	return os.WriteFile(*out, append(data, '\n'), 0o644)
}

func hitAt(hits []byte, id int) int {
	if id < len(hits) && hits[id] == 1 {
		return 1
	}
	return 0
}

func merge(byPath map[string]*reportFile, entry fileEntry, hits []byte) error {
	current := reportFile{Path: entry.Path, SHA256: entry.SHA256, Lines: entry.Lines, Status: entry.Status, Reason: entry.Reason,
		Statements: []statementHit{}, Outcomes: []outcomeHit{}}
	for _, u := range entry.Units {
		if u.Kind == "statement" {
			current.Statements = append(current.Statements, statementHit{Line: u.Line, Hits: hitAt(hits, u.ID)})
		} else {
			current.Outcomes = append(current.Outcomes, outcomeHit{Line: u.Line, Construct: u.Construct, Group: u.Group, Outcome: u.Outcome, Hits: hitAt(hits, u.ID)})
		}
	}
	known, ok := byPath[entry.Path]
	if !ok {
		byPath[entry.Path] = &current
		return nil
	}
	if known.SHA256 != current.SHA256 {
		return fmt.Errorf("%s differs between runs", entry.Path)
	}
	if known.Status == "inactive" {
		if current.Status == "inactive" && !strings.Contains(known.Reason, current.Reason) {
			known.Reason += "; " + current.Reason
		} else if current.Status == "measured" {
			*known = current
		}
		return nil
	}
	if current.Status == "inactive" {
		return nil
	}
	if len(known.Statements) != len(current.Statements) || len(known.Outcomes) != len(current.Outcomes) {
		return fmt.Errorf("%s was instrumented differently between runs", entry.Path)
	}
	for i := range known.Statements {
		if known.Statements[i].Line != current.Statements[i].Line {
			return fmt.Errorf("%s was instrumented differently between runs", entry.Path)
		}
		known.Statements[i].Hits |= current.Statements[i].Hits
	}
	for i := range known.Outcomes {
		a, b := &known.Outcomes[i], current.Outcomes[i]
		if a.Line != b.Line || a.Construct != b.Construct || a.Group != b.Group || a.Outcome != b.Outcome {
			return fmt.Errorf("%s was instrumented differently between runs", entry.Path)
		}
		a.Hits |= b.Hits
	}
	return nil
}

package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"sort"
	"strconv"
)

// Unit is one required measurement: an executed statement (executable line) or one outcome of a decision.
type Unit struct {
	ID        int    `json:"id"`
	Kind      string `json:"kind"` // "statement" or "outcome"
	Line      int    `json:"line"`
	Construct string `json:"construct,omitempty"`
	Group     string `json:"group,omitempty"`
	Outcome   string `json:"outcome,omitempty"`
}

type edit struct {
	offset int
	text   string
	closes bool
	seq    int
}

type rewriter struct {
	fset  *token.FileSet
	file  *ast.File
	name  string
	next  *int
	units []Unit
	edits []edit
	chain map[ast.Node]bool
	errs  []error
}

func (r *rewriter) offset(pos token.Pos) int { return r.fset.PositionFor(pos, false).Offset }
func (r *rewriter) line(pos token.Pos) int   { return r.fset.PositionFor(pos, false).Line }
func (r *rewriter) at(pos token.Pos) string {
	p := r.fset.PositionFor(pos, false)
	return strconv.Itoa(p.Line) + ":" + strconv.Itoa(p.Column)
}

func (r *rewriter) fail(pos token.Pos, message string) {
	r.errs = append(r.errs, fmt.Errorf("%s:%d: %s", r.name, r.line(pos), message))
}

func (r *rewriter) insert(offset int, text string) {
	r.edits = append(r.edits, edit{offset: offset, text: text, seq: len(r.edits)})
}

func (r *rewriter) closer(offset int, text string) {
	r.edits = append(r.edits, edit{offset: offset, text: text, closes: true, seq: len(r.edits)})
}

func (r *rewriter) unit(kind string, pos token.Pos, construct, group, outcome string) int {
	id := *r.next
	*r.next++
	r.units = append(r.units, Unit{ID: id, Kind: kind, Line: r.line(pos), Construct: construct, Group: group, Outcome: outcome})
	return id
}

// hit records the outcome at the point the inserted code runs.
func (r *rewriter) hit(offset int, pos token.Pos, construct, group, outcome string) {
	r.insert(offset, "clouseauHit("+strconv.Itoa(r.unit("outcome", pos, construct, group, outcome))+");")
}

// decide wraps a boolean expression so that the value it produces records which outcome it took, in place and
// without changing evaluation order.
func (r *rewriter) decide(expr ast.Expr, construct, group string) {
	t := r.unit("outcome", expr.Pos(), construct, group, "true")
	f := r.unit("outcome", expr.Pos(), construct, group, "false")
	r.insert(r.offset(expr.Pos()), fmt.Sprintf("clouseauB(%d,%d,", t, f))
	r.closer(r.offset(expr.End()), ")")
}

func leaves(expr ast.Expr, out *[]ast.Expr, chain map[ast.Node]bool) {
	switch e := expr.(type) {
	case *ast.ParenExpr:
		leaves(e.X, out, chain)
	case *ast.BinaryExpr:
		if e.Op == token.LAND || e.Op == token.LOR {
			chain[e] = true
			leaves(e.X, out, chain)
			leaves(e.Y, out, chain)
			return
		}
		*out = append(*out, expr)
	default:
		*out = append(*out, expr)
	}
}

func (r *rewriter) statementList(list []ast.Stmt) {
	for _, stmt := range list {
		switch stmt.(type) {
		case *ast.EmptyStmt, *ast.CaseClause, *ast.CommClause:
			continue
		}
		r.insert(r.offset(stmt.Pos()), "clouseauHit("+strconv.Itoa(r.unit("statement", stmt.Pos(), "", "", ""))+");")
		inner := stmt
		if labeled, ok := stmt.(*ast.LabeledStmt); ok {
			inner = labeled.Stmt
		}
		switch loop := inner.(type) {
		case *ast.RangeStmt:
			r.zeroEntry(stmt, loop.For, loop.Body, "range")
		case *ast.ForStmt:
			if loop.Cond != nil {
				r.zeroEntry(stmt, loop.For, loop.Body, "for")
				r.decide(loop.Cond, "for", r.at(loop.For))
			}
		}
	}
}

// zeroEntry reports a loop that finished without ever starting an iteration. The flag lives in a block around the
// loop, so `break` and `continue` keep their targets and the loop keeps its own scope.
func (r *rewriter) zeroEntry(stmt ast.Stmt, forPos token.Pos, body *ast.BlockStmt, construct string) {
	flag := "clouseauZ" + strconv.Itoa(*r.next)
	r.insert(r.offset(stmt.Pos()), "{var "+flag+" = true;")
	r.insert(r.offset(body.Lbrace)+1, flag+"=false;")
	if construct == "range" {
		r.hit(r.offset(body.Lbrace)+1, forPos, construct, r.at(forPos), "enter")
	}
	id := r.unit("outcome", forPos, construct, r.at(forPos), "zero-entry")
	r.closer(r.offset(stmt.End()), ";if "+flag+" {clouseauHit("+strconv.Itoa(id)+")}}")
}

func (r *rewriter) clauses(body *ast.BlockStmt, construct string, hasDefault func(ast.Stmt) bool, addDefault bool) {
	group := r.at(body.Lbrace)
	defaulted := false
	for _, stmt := range body.List {
		var colon token.Pos
		switch clause := stmt.(type) {
		case *ast.CaseClause:
			colon = clause.Colon
		case *ast.CommClause:
			colon = clause.Colon
		}
		outcome := "case@" + r.at(stmt.Pos())
		if hasDefault(stmt) {
			outcome, defaulted = "default", true
		}
		r.hit(r.offset(colon)+1, stmt.Pos(), construct, group, outcome)
	}
	if addDefault && !defaulted {
		id := r.unit("outcome", body.Lbrace, construct, group, "no-match")
		r.insert(r.offset(body.Rbrace), "default:clouseauHit("+strconv.Itoa(id)+");")
	}
}

func (r *rewriter) walk() {
	var stack []ast.Node
	ast.Inspect(r.file, func(node ast.Node) bool {
		if node == nil {
			stack = stack[:len(stack)-1]
			return true
		}
		stack = append(stack, node)
		switch n := node.(type) {
		case *ast.BlockStmt:
			r.statementList(n.List)
		case *ast.CaseClause:
			r.statementList(n.Body)
		case *ast.CommClause:
			r.statementList(n.Body)
		case *ast.IfStmt:
			r.decide(n.Cond, "if", r.at(n.If))
		case *ast.SwitchStmt:
			r.clauses(n.Body, "switch", func(s ast.Stmt) bool { return s.(*ast.CaseClause).List == nil }, true)
		case *ast.TypeSwitchStmt:
			r.clauses(n.Body, "typeswitch", func(s ast.Stmt) bool { return s.(*ast.CaseClause).List == nil }, true)
		case *ast.SelectStmt:
			r.clauses(n.Body, "select", func(s ast.Stmt) bool { return s.(*ast.CommClause).Comm == nil }, false)
		case *ast.BinaryExpr:
			if (n.Op == token.LAND || n.Op == token.LOR) && !r.chain[n] {
				r.operands(n, stack)
			}
		}
		return true
	})
}

func (r *rewriter) operands(root *ast.BinaryExpr, stack []ast.Node) {
	inBlock, inConst := false, false
	for _, parent := range stack {
		if _, ok := parent.(*ast.BlockStmt); ok {
			inBlock = true
		}
		if decl, ok := parent.(*ast.GenDecl); ok && decl.Tok == token.CONST {
			inConst = true
		}
	}
	if !inBlock || inConst {
		r.fail(root.Pos(), "short-circuit operator outside a function body or in a constant is not supported")
		return
	}
	var found []ast.Expr
	leaves(root, &found, r.chain)
	for _, leaf := range found {
		r.decide(leaf, "operand", r.at(leaf.Pos()))
	}
}

// instrument returns the rewritten source and the units it measures. Lines are unchanged: insertions never add
// a newline.
func instrument(name string, src []byte, next *int) ([]byte, []Unit, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, name, src, parser.ParseComments)
	if err != nil {
		return nil, nil, err
	}
	r := &rewriter{fset: fset, file: file, name: name, next: next, chain: map[ast.Node]bool{}}
	r.walk()
	if len(r.errs) > 0 {
		return nil, nil, r.errs[0]
	}
	return apply(src, r.edits), r.units, nil
}

func apply(src []byte, edits []edit) []byte {
	sort.SliceStable(edits, func(i, j int) bool {
		a, b := edits[i], edits[j]
		if a.offset != b.offset {
			return a.offset < b.offset
		}
		if a.closes != b.closes {
			return a.closes
		}
		if a.closes {
			return a.seq > b.seq
		}
		return a.seq < b.seq
	})
	var out []byte
	last := 0
	for _, e := range edits {
		out = append(out, src[last:e.offset]...)
		out = append(out, e.text...)
		last = e.offset
	}
	return append(out, src[last:]...)
}

